"""Math-only parity tests against frozen outputs of SHA-verified V4 source.

The oracle was generated by direct V4 calls with synthetic inputs; no model or
production risk pipeline is implemented here. All arithmetic uses float64.
"""
import math
import numpy as np
import pytest

V4_SOURCE_SHA256 = "8e33effb06d7f2e1fe855b1cb067fb2d27eb3aba9498e2af30be1b387534be7e"
CASES = [{'id': '01', 'r': [1, 0], 'va': [0, 0], 'vb': [0.0, 0.0], 'norm2': 0.0, 'v4': [0.0, 0.0, 1.0, 0.10087862273005652, 0.07459387702088953, 0.5, 0.16282927110181167], 'predicted_time': 1}, {'id': '02', 'r': [1, 0], 'va': [5, 0], 'vb': [5.0, 0.0], 'norm2': 0.0, 'v4': [0.0, 0.0, 1.0, 0.10087862273005652, 0.05942224101664088, 0.5, 0.1525125586189226], 'predicted_time': 13}, {'id': '03', 'r': [0.1, 0], 'va': [5, 0], 'vb': [5.0, 0.0], 'norm2': 0.0, 'v4': [0.0, 0.0, 0.1, 0.9688561694652216, 0.9316723694118842, 0.5, 0.8497999515359079], 'predicted_time': 3}, {'id': '04', 'r': [1, 0], 'va': [0, 0], 'vb': [-3.162277660168379e-05, 0.0], 'norm2': 9.999999999999996e-10, 'v4': [0.0, 0.0, 1.0, 0.10087862273005652, 0.05689660411494726, 1.0, 0.25079512552577093], 'predicted_time': 15}, {'id': '05', 'r': [1, 0], 'va': [0, 0], 'vb': [-3.1622776601683795e-05, 0.0], 'norm2': 1e-09, 'v4': [0.0, 0.0, 1.0, 0.10087862273005652, 0.05689660411494726, 1.0, 0.25079512552577093], 'predicted_time': 15}, {'id': '06', 'r': [1, 0], 'va': [0, 0], 'vb': [-3.16227766016838e-05, 0.0], 'norm2': 1.0000000000000005e-09, 'v4': [1897366.5961010272, 15.0, 0.9999920943058496, 0.07566232834790079, 0.05689660411494726, 1.0, 0.24776917019991224], 'predicted_time': 15}, {'id': '07', 'r': [1, 0], 'va': [0, 0], 'vb': [-2.0, 0.0], 'norm2': 4.0, 'v4': [30.0, 15.0, 0.5, 0.5389457944281422, 0.5586513717515126, 1.0, 0.6445564281224057], 'predicted_time': 15}, {'id': '08', 'r': [1, 0], 'va': [0, 0], 'vb': [2.0, 0.0], 'norm2': 4.0, 'v4': [-30.0, 0.0, 1.0, 0.10087862273005652, 0.059749809367121744, 1.0, 0.25273530509724956], 'predicted_time': 1}, {'id': '09', 'r': [1, 0], 'va': [0, 0], 'vb': [0.0, 2.0], 'norm2': 4.0, 'v4': [-0.0, -0.0, 1.0, 0.10087862273005652, 0.07432085984979866, 0.5, 0.1626436194254699], 'predicted_time': 1}, {'id': '10', 'r': [1, 0], 'va': [0, 0], 'vb': [-6.0, 0.0], 'norm2': 36.0, 'v4': [10.0, 10.0, 0.0, 0.8192375722777279, 0.8253847595836878, 1.0, 0.8595701451902351], 'predicted_time': 10}, {'id': '11', 'r': [2, 0], 'va': [0, 0], 'vb': [-6.0, 0.0], 'norm2': 36.0, 'v4': [20.0, 15.0, 0.5, 0.5389457944281422, 0.5586513717515126, 1.0, 0.6445564281224057], 'predicted_time': 15}, {'id': '12', 'r': [10, 0], 'va': [0, 0], 'vb': [-1e-05, 0.0], 'norm2': 1.0000000000000002e-10, 'v4': [0.0, 0.0, 10.0, 4.1774976453852733e-26, 7.419964618696503e-30, 1.0, 0.2], 'predicted_time': 15}, {'id': '13', 'r': [0, 0], 'va': [0, 0], 'vb': [2.0, 0.0], 'norm2': 4.0, 'v4': [-0.0, -0.0, 0.0, 0.9830850867332734, 0.9714630118716441, 1.0, 0.9785650584807108], 'predicted_time': 1}, {'id': '14', 'r': [1, 1], 'va': [0, 0], 'vb': [-6.0, 1e-12], 'norm2': 36.0, 'v4': [9.999999999998332, 9.999999999998332, 1.0000000000001668, 0.08406551894163783, 0.0632151500176334, 1.0, 0.25307416428498725], 'predicted_time': 10}]

@pytest.mark.parametrize("case", CASES, ids=["CPA-"+c["id"] for c in CASES])
def test_cpa_and_ccdri_float64_parity(case):
    r=np.array(case["r"],dtype=np.float64)
    va=np.array(case["va"],dtype=np.float64)
    vb=np.array(case["vb"],dtype=np.float64)
    v=vb-va;den=float(np.dot(v,v))
    raw=-60*float(np.dot(r,v))/den if den>1e-9 else 0.0
    clipped=max(0.0,min(15.0,raw))
    dcpa=math.hypot(*(r+v*clipped/60))
    def component(distance,time,scale):
        return 1/(1+math.exp(max(-100,min(100,(distance-.65)/scale))))*(1-.25*min(time,15)/15)
    current=component(dcpa,clipped,.16)
    a=np.zeros(2,dtype=np.float64); b=r.copy()
    distances=[math.hypot(*((a+va*k/60)-(b+vb*k/60))) for k in range(1,16)]
    time=min(range(15),key=distances.__getitem__)+1
    predicted=component(distances[time-1],time,.14)
    rule=case["v4"][5]
    risk=.68*predicted+.12*current+.20*rule
    np.testing.assert_allclose([raw,clipped,dcpa,current,predicted,rule,risk],case["v4"],rtol=1e-12,atol=1e-12)
    assert time==case["predicted_time"]


def test_near_zero_branch_boundaries():
    selected={c["id"]:c for c in CASES}
    assert selected["04"]["norm2"] < 1e-9
    assert selected["05"]["norm2"] == 1e-9
    assert selected["06"]["norm2"] > 1e-9
    assert selected["04"]["v4"][0] == selected["05"]["v4"][0] == 0
    assert selected["06"]["v4"][0] > 15
